import heapq
import math


def _cos(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na, nb = math.sqrt(sum(x * x for x in a)), math.sqrt(sum(y * y for y in b))
    return 0.0 if na == 0 or nb == 0 else dot / (na * nb)


def top_k(query, docs, k, min_score=None):
    if k < 1:
        raise ValueError('k must be >= 1')
    scored = ((doc_id, round(_cos(query, vec), 6)) for doc_id, vec in docs.items())
    if min_score is not None:
        scored = (t for t in scored if t[1] >= min_score)
    best = heapq.nsmallest(k, scored, key=lambda t: (-t[1], t[0]))
    return [[doc_id, score] for doc_id, score in best]
